import {createMovementDraft} from '../../src/features/entry/draftReducer'
import type {FoodRootV2,ExerciseRootV2,CurrentFoodRootV2,FoodRecord,FoodRootsV2,ExerciseRootsV2,OptionBackedExerciseRootV2} from '../../src/api/contracts'
import {foodBatchV2Fixture} from './entryV2'
import {exercisePreviewFixtureV2,workoutV2Draft,strengthOptionV2,cardioOptionV2} from './exerciseEntryV2'
import {exercisePreviewInput} from '../../src/features/workout/exerciseInputsV2'
const nutrients={energyKj:900,proteinGrams:10,fatGrams:4,carbsGrams:20}
export function savedDishV2():CurrentFoodRootV2{const input=foodBatchV2Fixture().entries[0];if(input.kind!=='DISH')throw Error();input.name='Saved shared recipe';input.ingredients.push({...input.ingredients[0],clientEntryId:'55555555-5555-4555-8555-555555555555',inputGrams:60},{...input.ingredients[1],clientEntryId:'66666666-6666-4666-8666-666666666666',inputGrams:30});return {id:'7',version:2,recordDate:'2020-01-02',source:'MANUAL',createdAt:'2020-01-02T01:00:00Z',updatedAt:'2020-01-02T01:00:00Z',input,preview:{kind:'DISH',clientEntryId:input.clientEntryId,leaves:input.ingredients.map(i=>({...i,consumedGrams:i.inputGrams/3,nutrients:{energyKj:i.inputGrams/3*9,proteinGrams:i.inputGrams/3*0.1,fatGrams:i.inputGrams/3*0.04,carbsGrams:i.inputGrams/3*0.2}})),totals:{energyKj:1620,proteinGrams:18,fatGrams:7.2,carbsGrams:36}},componentDetails:input.ingredients.map((i,index)=>({clientEntryId:i.clientEntryId,referenceId:i.referenceId,name:`Original ingredient ${index+1}`})),dataQuality:'CURRENT',displayName:'Saved shared recipe',componentCount:4}}
export function savedSingleV2():CurrentFoodRootV2{const dish=savedDishV2(),leaf=dish.preview.leaves[0];if(!leaf.referenceId)throw Error();return {...dish,id:'8',displayName:'Saved rice',componentCount:1,componentDetails:undefined,input:{kind:'SINGLE',clientEntryId:'88888888-8888-4888-8888-888888888888',referenceId:leaf.referenceId,quantityGrams:100,mealType:'DINNER'},preview:{kind:'SINGLE',clientEntryId:'88888888-8888-4888-8888-888888888888',leaves:[{...leaf,clientEntryId:'88888888-8888-4888-8888-888888888888',inputGrams:100,consumedGrams:100,nutrients}],totals:nutrients},dataQuality:'CURRENT'}}
export function savedWorkoutV2():OptionBackedExerciseRootV2{const draft=workoutV2Draft();draft.titleInput='Saved gym session';draft.periods[0].movements=[{...createMovementDraft({id:'301',displayName:'Saved bench press',bodyRegion:'CHEST',equipmentType:'BARBELL',loadBasis:'TOTAL_BARBELL',defaultPeriodOptionId:'201',allowedFields:['setCount','repetitions','loadKg']}),setCountInput:'3',repetitionsInput:'8',loadKgInput:'20'}];const input=exercisePreviewInput(draft),periods=input.entry.kind==='WORKOUT'?input.entry.periods:[input.entry.period],preview=exercisePreviewFixtureV2(input);return {id:'7',version:3,recordDate:draft.recordDate,source:'MANUAL',createdAt:'2020-01-02T01:00:00Z',updatedAt:'2020-01-02T01:00:00Z',input:input.entry.kind==='WORKOUT'?{...input.entry,periods:periods.map((p,i)=>({...p,calculationFingerprint:preview.periods[i].calculationFingerprint}))}:{...input.entry,period:{...periods[0],calculationFingerprint:preview.periods[0].calculationFingerprint}},preview,dataQuality:'CURRENT',displayName:'Saved gym session',periodCount:2,periodDetails:periods.map(p=>({clientEntryId:p.clientEntryId,optionId:p.optionId,name:p.periodKind==='STRENGTH'?strengthOptionV2.displayName:cardioOptionV2.displayName,option:p.periodKind==='STRENGTH'?strengthOptionV2:cardioOptionV2,selectableForNew:true,movements:p.periodKind==='STRENGTH'?[{catalogue:{id:'301',displayName:'Saved bench press',bodyRegion:'CHEST',equipmentType:'BARBELL',loadBasis:'TOTAL_BARBELL',defaultPeriodOptionId:'201',allowedFields:['setCount','repetitions','loadKg']},catalogueId:'301',name:'Saved bench press',loadBasis:'TOTAL_BARBELL',setCount:3,repetitions:8,loadKg:20,selectableForNew:true}]:[]}))}}

export function foodRecordRootFixture(row:FoodRecord):FoodRootV2{const clientEntryId=row.clientEntryId??'11111111-1111-4111-8111-111111111111';return {id:row.id,version:row.version,recordDate:row.recordDate,source:row.source,createdAt:row.createdAt,updatedAt:row.updatedAt,input:{kind:'SINGLE',clientEntryId,referenceId:row.reference?.referenceId??null,quantityGrams:row.quantityGrams,mealType:row.mealType},preview:{kind:'SINGLE',clientEntryId,leaves:[{clientEntryId,referenceId:row.reference?.referenceId??null,inputGrams:row.quantityGrams,consumedGrams:row.quantityGrams,nutrients:row.nutrients}],totals:row.nutrients},dataQuality:'LEGACY_UNVERIFIED',displayName:row.foodName,componentCount:1}}
export function rootPage<T extends FoodRootV2|ExerciseRootV2>(results:T[],page=0,totalMatches=results.length,hasMore=false){return {results,page,size:20,totalMatches,hasMore}}
export const emptyFoodRootPage=():FoodRootsV2=>rootPage([])
export const emptyExerciseRootPage=():ExerciseRootsV2=>rootPage([])
